async function consumeDailyMessageWithRetry(
  supabase: SupabaseClient,
  requestId: string
) {
  const maxAttempts = 3;

  for (
    let attempt = 1;
    attempt <= maxAttempts;
    attempt += 1
  ) {
    const {
      data,
      error,
    } =
      await (
        supabase.rpc as any
      )(
        "consume_daily_message",
        {
          p_request_id:
            requestId,
        }
      );

    if (!error) {
      return {
        data,
        error: null,
      };
    }

    console.error(
      `USAGE RPC ERROR (${attempt}/${maxAttempts}):`,
      "OPERATION_FAILED"
    );

    const text =
      typeof error.message ===
      "string"
        ? error.message.toLowerCase()
        : "";

    const retryable =
      text.includes("timeout") ||
      text.includes(
        "temporarily unavailable"
      ) ||
      text.includes(
        "fetch failed"
      );

    if (
      !retryable ||
      attempt === maxAttempts
    ) {
      return {
        data: null,
        error,
      };
    }

    await new Promise(
      (resolve) =>
        setTimeout(
          resolve,
          500 * attempt
        )
    );
  }

  return {
    data: null,
    error: new Error(
      "Usage retry failed"
    ),
  };
}

